const TOTAL_PREGUNTAS = 9;
const data = $getWorkflowStaticData('global');
const participantes = data.participantes || {};

const ranking = Object.keys(participantes)
  .map(function (nombre) { return { nombre: nombre, puntaje: participantes[nombre].puntaje }; })
  .sort(function (a, b) { return b.puntaje - a.puntaje; });

const medallas = ['🥇', '🥈', '🥉'];
const lineas = ranking.map(function (r, i) {
  const prefijo = medallas[i] || ((i + 1) + '.');
  return prefijo + ' ' + r.nombre + ' - ' + r.puntaje + '/' + TOTAL_PREGUNTAS + ' puntos';
});

const tabla = '🏆 ¡Trivia terminada! Tabla de clasificación final:\n\n' + lineas.join('\n');

return [{
  json: {
    chat_id_admin: data.adminChatId || null,
    mensaje_telegram: tabla,
    tabla_texto: tabla
  }
}];

const data = $getWorkflowStaticData('global');
